insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (46, 'draft', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'パンを <u>焼きます</u>。', '["やきます","わたします","むかいます","にゅうりょくします"]'::jsonb, 0, '焼きます dibaca “やきます” dan berarti membakar/memanggang.', 'Bab 46–50 · Mondai 1 No.1', 'kanji:焼きます'),
  (46, 'draft', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にもつを <u>渡します</u>。', '["わたします","やきます","むかいます","でます"]'::jsonb, 0, '渡します dibaca “わたします” dan berarti menyerahkan.', 'Bab 46–50 · Mondai 1 No.2', 'kanji:渡します'),
  (46, 'draft', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'えきへ <u>向かいます</u>。', '["むかいます","わたします","やきます","でます"]'::jsonb, 0, '向かいます dibaca “むかいます” dan berarti menuju ke.', 'Bab 46–50 · Mondai 1 No.3', 'kanji:向かいます'),
  (46, 'draft', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ともだちが <u>集まります</u>。', '["あつまります","わかれます","くらべます","しりあいます"]'::jsonb, 0, '集まります dibaca “あつまります” dan berarti berkumpul.', 'Bab 46–50 · Mondai 1 No.4', 'kanji:集まります'),
  (46, 'draft', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'くうこうで ともだちと <u>別れます</u>。', '["わかれます","あつまります","くらべます","しりあいます"]'::jsonb, 0, '別れます dibaca “わかれます” dan berarti berpisah.', 'Bab 46–50 · Mondai 1 No.5', 'kanji:別れます'),
  (46, 'draft', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にもつを <u>下ろします</u>。', '["おろします","とどけます","せわをします","たのしみます"]'::jsonb, 0, '下ろします dibaca “おろします” dan berarti menurunkan.', 'Bab 46–50 · Mondai 1 No.6', 'kanji:下ろします'),
  (46, 'draft', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にもつを うちまで <u>届けます</u>。', '["とどけます","おろします","せわをします","たのしみます"]'::jsonb, 0, '届けます dibaca “とどけます” dan berarti mengantarkan.', 'Bab 46–50 · Mondai 1 No.7', 'kanji:届けます'),
  (46, 'draft', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'かいしゃに <u>努めます</u>。', '["つとめます","やすみます","すごします","よります"]'::jsonb, 0, '努めます dibaca “つとめます” dan berarti bekerja (untuk perusahaan).', 'Bab 46–50 · Mondai 1 No.8', 'kanji:努めます'),
  (46, 'draft', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'いすに <u>掛けます</u>。', '["かけます","やすみます","すごします","よります"]'::jsonb, 0, '掛けます dibaca “かけます” dan berarti duduk (di kursi).', 'Bab 46–50 · Mondai 1 No.9', 'kanji:掛けます'),
  (46, 'draft', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せかいに <u>感謝します</u>。', '["かんしゃします","きんちょうします","ほうそうします","きょうりょくします"]'::jsonb, 0, '感謝します dibaca “かんしゃします” dan berarti mengucapkan terima kasih.', 'Bab 46–50 · Mondai 1 No.10', 'kanji:感謝します'),
  (46, 'draft', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'びょうきの <u>げんいん</u>を しらべます。', '["原因","知識","具合","注射"]'::jsonb, 0, 'げんいん ditulis 原因, berarti penyebab.', 'Bab 46–50 · Mondai 2 No.11', 'kanji:原因'),
  (46, 'draft', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'びょういんで <u>ちゅうしゃ</u>を うけます。', '["注射","原因","具合","宝庫"]'::jsonb, 0, 'ちゅうしゃ ditulis 注射, berarti suntikan.', 'Bab 46–50 · Mondai 2 No.12', 'kanji:注射'),
  (46, 'draft', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にほんごの <u>ちしき</u>を ふやします。', '["知識","宝庫","原因","注射"]'::jsonb, 0, 'ちしき ditulis 知識, berarti pengetahuan.', 'Bab 46–50 · Mondai 2 No.13', 'kanji:知識'),
  (46, 'draft', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にほんの <u>じんこう</u>を しらべます。', '["人口","科学","医学","文学"]'::jsonb, 0, 'じんこう ditulis 人口, berarti jumlah penduduk.', 'Bab 46–50 · Mondai 2 No.14', 'kanji:人口'),
  (46, 'draft', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'だいがくで <u>かがく</u>を べんきょうします。', '["科学","医学","文学","人口"]'::jsonb, 0, 'かがく ditulis 科学, berarti ilmu pengetahuan.', 'Bab 46–50 · Mondai 2 No.15', 'kanji:科学'),
  (46, 'draft', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもの <u>せわ</u>を します。', '["世話","営業","芸","自然"]'::jsonb, 0, 'せわ ditulis 世話, berarti mengurus.', 'Bab 46–50 · Mondai 2 No.16', 'kanji:世話をします'),
  (46, 'draft', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せんせいは <u>きびしい</u>です。', '["厳しい","美しい","嫌な","久しぶり"]'::jsonb, 0, 'きびしい ditulis 厳しい, berarti disiplin/keras.', 'Bab 46–50 · Mondai 2 No.17', 'kanji:厳しい'),
  (46, 'draft', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'けしきが とても <u>うつくしい</u>です。', '["美しい","厳しい","嫌な","自然"]'::jsonb, 0, 'うつくしい ditulis 美しい, berarti indah.', 'Bab 46–50 · Mondai 2 No.18', 'kanji:美しい'),
  (46, 'draft', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'りょこうの けいけんを <u>いかします</u>。', '["生かします","感謝します","協力します","撮ります"]'::jsonb, 0, 'いかします ditulis 生かします, berarti memanfaatkan.', 'Bab 46–50 · Mondai 2 No.19', 'kanji:生かします'),
  (46, 'draft', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'みんなで <u>きょうりょくします</u>。', '["協力します","感謝します","放送します","生かします"]'::jsonb, 0, 'きょうりょくします ditulis 協力します, berarti bekerja sama.', 'Bab 46–50 · Mondai 2 No.20', 'kanji:協力します'),
  (46, 'draft', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ねている</span><span class="arrange-chip"><b>②</b>が</span><span class="arrange-chip"><b>③</b>ふりました。</span><span class="arrange-chip"><b>④</b>に</span><span class="arrange-chip"><b>⑤</b>あいだ</span><span class="arrange-chip"><b>⑥</b>あめ</span></div><small>Petunjuk arti: “Selagi tidur, hujan turun.”</small>', '["①→⑤→④→⑥→②→③","⑤→①→④→⑥→②→③","①→④→⑤→⑥→②→③","①→⑤→⑥→④→②→③"]'::jsonb, 0, 'Urutan yang benar: ①ねている→⑤あいだ→④に→⑥あめ→②が→③ふりました。 に menandai waktu berlangsungnya kejadian lain, dipakai setelah Vているあいだ untuk menyatakan tindakan yang terjadi bersamaan (Pel.46).', 'Bab 46–50 · Mondai 3 No.21', 'materi:book2:20:0'),
  (46, 'draft', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ところです。</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>ごはん</span><span class="arrange-chip"><b>④</b>いま</span><span class="arrange-chip"><b>⑤</b>たべた</span></div><small>Petunjuk arti: “Saya baru saja makan.”</small>', '["④→③→②→⑤→①","③→④→②→⑤→①","④→②→③→⑤→①","④→③→⑤→②→①"]'::jsonb, 0, 'Urutan yang benar: ④いま→③ごはん→②を→⑤たべた→①ところです。 を menandai objek たべた sebelum pola Vたところです yang menyatakan tindakan baru selesai (Pel.46).', 'Bab 46–50 · Mondai 3 No.22', 'materi:book2:20:0'),
  (46, 'draft', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>でんわしている</span><span class="arrange-chip"><b>②</b>ところです。</span><span class="arrange-chip"><b>③</b>せんせい</span><span class="arrange-chip"><b>④</b>いま</span><span class="arrange-chip"><b>⑤</b>に</span></div><small>Petunjuk arti: “Saya sedang menelepon dengan guru sekarang.”</small>', '["④→③→⑤→①→②","③→④→⑤→①→②","④→⑤→③→①→②","④→③→①→⑤→②"]'::jsonb, 0, 'Urutan yang benar: ④いま→③せんせい→⑤に→①でんわしている→②ところです。 に menandai lawan bicara sebelum でんわしている, dan ところです menyatakan tindakan sedang tepat berlangsung (Pel.46).', 'Bab 46–50 · Mondai 3 No.23', 'materi:book2:20:0'),
  (46, 'draft', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>に</span><span class="arrange-chip"><b>②</b>わたし</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>と</span><span class="arrange-chip"><b>⑤</b>もっと</span><span class="arrange-chip"><b>⑥</b>せんせい</span><span class="arrange-chip"><b>⑦</b>れんしゅうしなさい</span><span class="arrange-chip"><b>⑧</b>いわれました。</span></div><small>Petunjuk arti: “Saya diberi tahu guru agar lebih banyak berlatih.”</small>', '["②→③→⑥→①→⑤→⑦→④→⑧","③→②→⑥→①→⑤→⑦→④→⑧","②→⑥→③→①→⑤→⑦→④→⑧","②→③→①→⑥→⑤→⑦→④→⑧"]'::jsonb, 0, 'Urutan yang benar: ②わたし→③は→⑥せんせい→①に→⑤もっと→⑦れんしゅうしなさい→④と→⑧いわれました。 に menandai pelaku perkataan (guru) sebelum pola ～と言われました yang menyampaikan perkataan orang lain (Pel.47).', 'Bab 46–50 · Mondai 3 No.24', 'materi:book2:21:0'),
  (46, 'draft', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はは</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>ねる</span><span class="arrange-chip"><b>④</b>はやく</span><span class="arrange-chip"><b>⑤</b>いいました。</span><span class="arrange-chip"><b>⑥</b>ように</span></div><small>Petunjuk arti: “Ibu berkata agar saya tidur lebih cepat.”</small>', '["①→②→④→③→⑥→⑤","②→①→④→③→⑥→⑤","①→④→②→③→⑥→⑤","①→②→③→④→⑥→⑤"]'::jsonb, 0, 'Urutan yang benar: ①はは→②は→④はやく→③ねる→⑥ように→⑤いいました。 は menandai topik はは sebelum pola ～ように言いました yang menyampaikan instruksi tidak langsung (Pel.47).', 'Bab 46–50 · Mondai 3 No.25', 'materi:book2:21:0'),
  (46, 'draft', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>でんわを</span><span class="arrange-chip"><b>②</b>くださいと</span><span class="arrange-chip"><b>③</b>たなかさん</span><span class="arrange-chip"><b>④</b>いただけませんか。</span><span class="arrange-chip"><b>⑤</b>に</span><span class="arrange-chip"><b>⑥</b>つたえて</span></div><small>Petunjuk arti: “Bisakah Anda menyampaikan kepada Tanaka agar menelepon saya?”</small>', '["③→⑤→①→②→⑥→④","⑤→③→①→②→⑥→④","③→①→⑤→②→⑥→④","③→⑤→②→①→⑥→④"]'::jsonb, 0, 'Urutan yang benar: ③たなかさん→⑤に→①でんわを→②くださいと→⑥つたえて→④いただけませんか。 に menandai penerima pesan sebelum pola ～と伝えていただけませんか yang meminta tolong menyampaikan pesan dengan sopan (Pel.47).', 'Bab 46–50 · Mondai 3 No.26', 'materi:book2:21:0'),
  (46, 'draft', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>からです。</span><span class="arrange-chip"><b>②</b>べんきょうする</span><span class="arrange-chip"><b>③</b>の</span><span class="arrange-chip"><b>④</b>にほんご</span><span class="arrange-chip"><b>⑤</b>にほんで</span><span class="arrange-chip"><b>⑥</b>を</span><span class="arrange-chip"><b>⑦</b>は</span><span class="arrange-chip"><b>⑧</b>はたらきたい</span></div><small>Petunjuk arti: “Saya belajar bahasa Jepang karena ingin bekerja di Jepang.”</small>', '["④→⑥→②→③→⑦→⑤→⑧→①","⑥→④→②→③→⑦→⑤→⑧→①","④→②→⑥→③→⑦→⑤→⑧→①","④→⑥→③→②→⑦→⑤→⑧→①"]'::jsonb, 0, 'Urutan yang benar: ④にほんご→⑥を→②べんきょうする→③の→⑦は→⑤にほんで→⑧はたらきたい→①からです。 の menominalkan べんきょうする sebelum は pada pola ～のは～からです yang menjelaskan alasan dengan bentuk nominal (Pel.48).', 'Bab 46–50 · Mondai 3 No.27', 'materi:book2:22:0'),
  (46, 'draft', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>ために</span><span class="arrange-chip"><b>③</b>たいふう</span><span class="arrange-chip"><b>④</b>とまりました。</span><span class="arrange-chip"><b>⑤</b>でんしゃ</span><span class="arrange-chip"><b>⑥</b>の</span></div><small>Petunjuk arti: “Karena topan, kereta berhenti.”</small>', '["③→⑥→②→⑤→①→④","⑥→③→②→⑤→①→④","③→②→⑥→⑤→①→④","③→⑥→⑤→②→①→④"]'::jsonb, 0, 'Urutan yang benar: ③たいふう→⑥の→②ために→⑤でんしゃ→①が→④とまりました。 の menghubungkan Kata Benda dengan ために pada pola Nのために untuk menyatakan sebab secara formal, dipakai sebelum akibatnya でんしゃがとまりました (Pel.48).', 'Bab 46–50 · Mondai 3 No.28', 'materi:book2:22:0'),
  (46, 'draft', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>すわります。</span><span class="arrange-chip"><b>②</b>ように</span><span class="arrange-chip"><b>③</b>まえ</span><span class="arrange-chip"><b>④</b>に</span><span class="arrange-chip"><b>⑤</b>みえる</span><span class="arrange-chip"><b>⑥</b>よく</span></div><small>Petunjuk arti: “Saya duduk di depan agar terlihat jelas.”</small>', '["⑥→⑤→②→③→④→①","⑤→⑥→②→③→④→①","⑥→②→⑤→③→④→①","⑥→⑤→③→②→④→①"]'::jsonb, 0, 'Urutan yang benar: ⑥よく→⑤みえる→②ように→③まえ→④に→①すわります。 に menandai tempat まえ sebelum すわります, didahului anak kalimat tujuan よくみえるように (Pel.48).', 'Bab 46–50 · Mondai 3 No.29', 'materi:book2:22:0'),
  (46, 'draft', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>もう</span><span class="arrange-chip"><b>②</b>なりました。</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>おかえりに</span><span class="arrange-chip"><b>⑤</b>ぶちょう</span></div><small>Petunjuk arti: “Kepala bagian sudah pulang.”</small>', '["⑤→③→①→④→②","③→⑤→①→④→②","⑤→①→③→④→②","⑤→③→④→①→②"]'::jsonb, 0, 'Urutan yang benar: ⑤ぶちょう→③は→①もう→④おかえりに→②なりました。 は menandai topik ぶちょう sebelum pola お帰りになりました yang menyatakan tindakan orang yang dihormati (Pel.49).', 'Bab 46–50 · Mondai 3 No.30', 'materi:book2:23:0'),
  (46, 'draft', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>こちら</span><span class="arrange-chip"><b>②</b>ごらん</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>ください。</span></div><small>Petunjuk arti: “Silakan lihat ini.”</small>', '["①→③→②→④","③→①→②→④","①→②→③→④","①→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ①こちら→③を→②ごらん→④ください。 Pola お／ご～ください dipakai untuk meminta dengan sangat sopan, di sini bersama ご覧ください (Pel.49).', 'Bab 46–50 · Mondai 4 No.31', 'materi:book2:23:0'),
  (46, 'draft', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>します。</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>おもち</span><span class="arrange-chip"><b>④</b>にもつ</span></div><small>Petunjuk arti: “Saya akan membawakan barang Anda.”</small>', '["④→②→③→①","②→④→③→①","④→③→②→①","④→②→①→③"]'::jsonb, 0, 'Urutan yang benar: ④にもつ→②を→③おもち→①します。 Pola お／ご～します merendahkan tindakan pembicara sendiri untuk menghormati lawan bicara, di sini bersama お持ちします (Pel.49).', 'Bab 46–50 · Mondai 4 No.32', 'materi:book2:23:0'),
  (46, 'draft', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>あったら</span><span class="arrange-chip"><b>②</b>ふくしゅうして</span><span class="arrange-chip"><b>③</b>ください。</span><span class="arrange-chip"><b>④</b>じかん</span><span class="arrange-chip"><b>⑤</b>が</span></div><small>Petunjuk arti: “Jika ada waktu, silakan mengulang pelajaran.”</small>', '["④→⑤→①→②→③","⑤→④→①→②→③","④→①→⑤→②→③","④→⑤→②→①→③"]'::jsonb, 0, 'Urutan yang benar: ④じかん→⑤が→①あったら→②ふくしゅうして→③ください。 Pola ～たら menyatakan pengandaian dan sekaligus saran sesuai situasi yang mungkin terjadi (Pel.50).', 'Bab 46–50 · Mondai 4 No.33', 'materi:book2:24:0'),
  (46, 'draft', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>おもいます。</span><span class="arrange-chip"><b>②</b>これからも</span><span class="arrange-chip"><b>③</b>べんきょうを</span><span class="arrange-chip"><b>④</b>と</span><span class="arrange-chip"><b>⑤</b>つづけよう</span></div><small>Petunjuk arti: “Saya berpikir akan terus belajar mulai sekarang juga.”</small>', '["②→③→⑤→④→①","③→②→⑤→④→①","②→⑤→③→④→①","②→③→④→⑤→①"]'::jsonb, 0, 'Urutan yang benar: ②これからも→③べんきょうを→⑤つづけよう→④と→①おもいます。 Pola 普通形＋と思います menyatakan pendapat atau rencana pribadi pembicara sendiri (Pel.50).', 'Bab 46–50 · Mondai 4 No.34', 'materi:book2:24:0'),
  (46, 'draft', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>まいにち</span><span class="arrange-chip"><b>②</b>しています。</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>ように</span><span class="arrange-chip"><b>⑤</b>にほんご</span><span class="arrange-chip"><b>⑥</b>よむ</span></div><small>Petunjuk arti: “Saya membiasakan membaca bahasa Jepang setiap hari.”</small>', '["①→⑤→③→⑥→④→②","⑤→①→③→⑥→④→②","①→③→⑤→⑥→④→②","①→⑤→⑥→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ①まいにち→⑤にほんご→③を→⑥よむ→④ように→②しています。 Pola ～ようにしています menyatakan kebiasaan yang diusahakan secara berkelanjutan, berbeda dari niat sesaat (Pel.50).', 'Bab 46–50 · Mondai 4 No.35', 'materi:book2:24:0'),
  (46, 'draft', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'いま　ごはんを　たべたところです。でも、はは　に　でんわしている　ところです、と　うそを　いいました。<br><small>ほんとうは、いま　なにを　していますか。</small>', '["ごはんを たべたばかり","でんわをしているところ","でかけているところ","ねているところ"]'::jsonb, 0, 'Vたところです menyatakan tindakan yang BARU SAJA SELESAI (baru makan), berbeda dari Vているところです yang menyatakan tindakan SEDANG BERLANGSUNG (sedang menelepon) — yang sungguhan terjadi di sini adalah yang pertama (Pel.46).', 'Bab 46–50 · Soal Cerita No.36', 'materi:book2:20:0'),
  (46, 'draft', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'せんせいに、もっと　れんしゅうしなさいと　いわれました。だから、はは　に、はやく　ねるように　いいました。<br><small>「はやく　ねるように　いいました」は、だれが　だれに　いいましたか。</small>', '["わたしが ははに","ははが わたしに","せんせいが わたしに","わたしが せんせいに"]'::jsonb, 1, '～ように言いました menyampaikan instruksi TIDAK LANGSUNG dari subjek kalimat (はは) kepada objek (に) — jadi ibu yang menyuruh saya, bukan sebaliknya; berbeda dari ～と言われました yang menyampaikan perkataan yang diterima DARI orang lain (Pel.47).', 'Bab 46–50 · Soal Cerita No.37', 'materi:book2:21:0'),
  (46, 'draft', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'にほんごを　べんきょうするのは、にほんで　はたらきたいからです。にほんで　はたらく　ために、まいにち　れんしゅうしています。<br><small>「べんきょうするのは～からです」で　せつめいしている ことは、なんですか。</small>', '["べんきょうする りゆう","れんしゅうする ばしょ","はたらく かいしゃ","にほんごの レベル"]'::jsonb, 0, '～のは～からです menjelaskan ALASAN dari suatu keadaan dengan bentuk nominal, sedangkan ために pada kalimat kedua menyatakan TUJUAN dari tindakan れんしゅうしています — dua pola berbeda fungsi meski sama-sama berkaitan dengan はたらきたい (Pel.48).', 'Bab 46–50 · Soal Cerita No.38', 'materi:book2:22:0'),
  (46, 'draft', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ぶちょうは　もう　おかえりに　なりました。わたしは　ぶちょうの　にもつを　おもちしました。<br><small>「おもちしました」を したのは、だれですか。</small>', '["ぶちょう","わたし","かいしゃ","おきゃくさま"]'::jsonb, 1, 'お持ちします adalah pola お／ご～します yang MERENDAHKAN tindakan PEMBICARA SENDIRI (saya yang membawakan), berbeda dari お帰りになりました yang MENGHORMATI tindakan orang lain (kepala bagian yang pulang) (Pel.49).', 'Bab 46–50 · Soal Cerita No.39', 'materi:book2:23:0'),
  (46, 'draft', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは、まいにち　にほんごを　よむように　しています。じかんが　あったら、ふくしゅうも　します。これからも　べんきょうを　つづけようと　おもいます。<br><small>まいにち　かならず　して　いる ことは、なんですか。</small>', '["にほんごを よむこと","ふくしゅうすること","じかんを つくること","あたらしいことを はじめること"]'::jsonb, 0, '～ようにしています menyatakan KEBIASAAN yang diusahakan secara BERKELANJUTAN (setiap hari membaca), berbeda dari ～たら yang hanya SYARAT bersyarat (jika ada waktu, baru mengulang) — hanya yang pertama pasti dilakukan tiap hari (Pel.50).', 'Bab 46–50 · Soal Cerita No.40', 'materi:book2:24:0');
insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (46, 'published', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'パンを <u>焼きます</u>。', '["やきます","わたします","むかいます","にゅうりょくします"]'::jsonb, 0, '焼きます dibaca “やきます” dan berarti membakar/memanggang.', 'Bab 46–50 · Mondai 1 No.1', 'kanji:焼きます'),
  (46, 'published', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にもつを <u>渡します</u>。', '["わたします","やきます","むかいます","でます"]'::jsonb, 0, '渡します dibaca “わたします” dan berarti menyerahkan.', 'Bab 46–50 · Mondai 1 No.2', 'kanji:渡します'),
  (46, 'published', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'えきへ <u>向かいます</u>。', '["むかいます","わたします","やきます","でます"]'::jsonb, 0, '向かいます dibaca “むかいます” dan berarti menuju ke.', 'Bab 46–50 · Mondai 1 No.3', 'kanji:向かいます'),
  (46, 'published', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ともだちが <u>集まります</u>。', '["あつまります","わかれます","くらべます","しりあいます"]'::jsonb, 0, '集まります dibaca “あつまります” dan berarti berkumpul.', 'Bab 46–50 · Mondai 1 No.4', 'kanji:集まります'),
  (46, 'published', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'くうこうで ともだちと <u>別れます</u>。', '["わかれます","あつまります","くらべます","しりあいます"]'::jsonb, 0, '別れます dibaca “わかれます” dan berarti berpisah.', 'Bab 46–50 · Mondai 1 No.5', 'kanji:別れます'),
  (46, 'published', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にもつを <u>下ろします</u>。', '["おろします","とどけます","せわをします","たのしみます"]'::jsonb, 0, '下ろします dibaca “おろします” dan berarti menurunkan.', 'Bab 46–50 · Mondai 1 No.6', 'kanji:下ろします'),
  (46, 'published', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にもつを うちまで <u>届けます</u>。', '["とどけます","おろします","せわをします","たのしみます"]'::jsonb, 0, '届けます dibaca “とどけます” dan berarti mengantarkan.', 'Bab 46–50 · Mondai 1 No.7', 'kanji:届けます'),
  (46, 'published', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'かいしゃに <u>努めます</u>。', '["つとめます","やすみます","すごします","よります"]'::jsonb, 0, '努めます dibaca “つとめます” dan berarti bekerja (untuk perusahaan).', 'Bab 46–50 · Mondai 1 No.8', 'kanji:努めます'),
  (46, 'published', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'いすに <u>掛けます</u>。', '["かけます","やすみます","すごします","よります"]'::jsonb, 0, '掛けます dibaca “かけます” dan berarti duduk (di kursi).', 'Bab 46–50 · Mondai 1 No.9', 'kanji:掛けます'),
  (46, 'published', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せかいに <u>感謝します</u>。', '["かんしゃします","きんちょうします","ほうそうします","きょうりょくします"]'::jsonb, 0, '感謝します dibaca “かんしゃします” dan berarti mengucapkan terima kasih.', 'Bab 46–50 · Mondai 1 No.10', 'kanji:感謝します'),
  (46, 'published', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'びょうきの <u>げんいん</u>を しらべます。', '["原因","知識","具合","注射"]'::jsonb, 0, 'げんいん ditulis 原因, berarti penyebab.', 'Bab 46–50 · Mondai 2 No.11', 'kanji:原因'),
  (46, 'published', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'びょういんで <u>ちゅうしゃ</u>を うけます。', '["注射","原因","具合","宝庫"]'::jsonb, 0, 'ちゅうしゃ ditulis 注射, berarti suntikan.', 'Bab 46–50 · Mondai 2 No.12', 'kanji:注射'),
  (46, 'published', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にほんごの <u>ちしき</u>を ふやします。', '["知識","宝庫","原因","注射"]'::jsonb, 0, 'ちしき ditulis 知識, berarti pengetahuan.', 'Bab 46–50 · Mondai 2 No.13', 'kanji:知識'),
  (46, 'published', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にほんの <u>じんこう</u>を しらべます。', '["人口","科学","医学","文学"]'::jsonb, 0, 'じんこう ditulis 人口, berarti jumlah penduduk.', 'Bab 46–50 · Mondai 2 No.14', 'kanji:人口'),
  (46, 'published', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'だいがくで <u>かがく</u>を べんきょうします。', '["科学","医学","文学","人口"]'::jsonb, 0, 'かがく ditulis 科学, berarti ilmu pengetahuan.', 'Bab 46–50 · Mondai 2 No.15', 'kanji:科学'),
  (46, 'published', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもの <u>せわ</u>を します。', '["世話","営業","芸","自然"]'::jsonb, 0, 'せわ ditulis 世話, berarti mengurus.', 'Bab 46–50 · Mondai 2 No.16', 'kanji:世話をします'),
  (46, 'published', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せんせいは <u>きびしい</u>です。', '["厳しい","美しい","嫌な","久しぶり"]'::jsonb, 0, 'きびしい ditulis 厳しい, berarti disiplin/keras.', 'Bab 46–50 · Mondai 2 No.17', 'kanji:厳しい'),
  (46, 'published', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'けしきが とても <u>うつくしい</u>です。', '["美しい","厳しい","嫌な","自然"]'::jsonb, 0, 'うつくしい ditulis 美しい, berarti indah.', 'Bab 46–50 · Mondai 2 No.18', 'kanji:美しい'),
  (46, 'published', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'りょこうの けいけんを <u>いかします</u>。', '["生かします","感謝します","協力します","撮ります"]'::jsonb, 0, 'いかします ditulis 生かします, berarti memanfaatkan.', 'Bab 46–50 · Mondai 2 No.19', 'kanji:生かします'),
  (46, 'published', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'みんなで <u>きょうりょくします</u>。', '["協力します","感謝します","放送します","生かします"]'::jsonb, 0, 'きょうりょくします ditulis 協力します, berarti bekerja sama.', 'Bab 46–50 · Mondai 2 No.20', 'kanji:協力します'),
  (46, 'published', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ねている</span><span class="arrange-chip"><b>②</b>が</span><span class="arrange-chip"><b>③</b>ふりました。</span><span class="arrange-chip"><b>④</b>に</span><span class="arrange-chip"><b>⑤</b>あいだ</span><span class="arrange-chip"><b>⑥</b>あめ</span></div><small>Petunjuk arti: “Selagi tidur, hujan turun.”</small>', '["①→⑤→④→⑥→②→③","⑤→①→④→⑥→②→③","①→④→⑤→⑥→②→③","①→⑤→⑥→④→②→③"]'::jsonb, 0, 'Urutan yang benar: ①ねている→⑤あいだ→④に→⑥あめ→②が→③ふりました。 に menandai waktu berlangsungnya kejadian lain, dipakai setelah Vているあいだ untuk menyatakan tindakan yang terjadi bersamaan (Pel.46).', 'Bab 46–50 · Mondai 3 No.21', 'materi:book2:20:0'),
  (46, 'published', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ところです。</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>ごはん</span><span class="arrange-chip"><b>④</b>いま</span><span class="arrange-chip"><b>⑤</b>たべた</span></div><small>Petunjuk arti: “Saya baru saja makan.”</small>', '["④→③→②→⑤→①","③→④→②→⑤→①","④→②→③→⑤→①","④→③→⑤→②→①"]'::jsonb, 0, 'Urutan yang benar: ④いま→③ごはん→②を→⑤たべた→①ところです。 を menandai objek たべた sebelum pola Vたところです yang menyatakan tindakan baru selesai (Pel.46).', 'Bab 46–50 · Mondai 3 No.22', 'materi:book2:20:0'),
  (46, 'published', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>でんわしている</span><span class="arrange-chip"><b>②</b>ところです。</span><span class="arrange-chip"><b>③</b>せんせい</span><span class="arrange-chip"><b>④</b>いま</span><span class="arrange-chip"><b>⑤</b>に</span></div><small>Petunjuk arti: “Saya sedang menelepon dengan guru sekarang.”</small>', '["④→③→⑤→①→②","③→④→⑤→①→②","④→⑤→③→①→②","④→③→①→⑤→②"]'::jsonb, 0, 'Urutan yang benar: ④いま→③せんせい→⑤に→①でんわしている→②ところです。 に menandai lawan bicara sebelum でんわしている, dan ところです menyatakan tindakan sedang tepat berlangsung (Pel.46).', 'Bab 46–50 · Mondai 3 No.23', 'materi:book2:20:0'),
  (46, 'published', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>に</span><span class="arrange-chip"><b>②</b>わたし</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>と</span><span class="arrange-chip"><b>⑤</b>もっと</span><span class="arrange-chip"><b>⑥</b>せんせい</span><span class="arrange-chip"><b>⑦</b>れんしゅうしなさい</span><span class="arrange-chip"><b>⑧</b>いわれました。</span></div><small>Petunjuk arti: “Saya diberi tahu guru agar lebih banyak berlatih.”</small>', '["②→③→⑥→①→⑤→⑦→④→⑧","③→②→⑥→①→⑤→⑦→④→⑧","②→⑥→③→①→⑤→⑦→④→⑧","②→③→①→⑥→⑤→⑦→④→⑧"]'::jsonb, 0, 'Urutan yang benar: ②わたし→③は→⑥せんせい→①に→⑤もっと→⑦れんしゅうしなさい→④と→⑧いわれました。 に menandai pelaku perkataan (guru) sebelum pola ～と言われました yang menyampaikan perkataan orang lain (Pel.47).', 'Bab 46–50 · Mondai 3 No.24', 'materi:book2:21:0'),
  (46, 'published', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はは</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>ねる</span><span class="arrange-chip"><b>④</b>はやく</span><span class="arrange-chip"><b>⑤</b>いいました。</span><span class="arrange-chip"><b>⑥</b>ように</span></div><small>Petunjuk arti: “Ibu berkata agar saya tidur lebih cepat.”</small>', '["①→②→④→③→⑥→⑤","②→①→④→③→⑥→⑤","①→④→②→③→⑥→⑤","①→②→③→④→⑥→⑤"]'::jsonb, 0, 'Urutan yang benar: ①はは→②は→④はやく→③ねる→⑥ように→⑤いいました。 は menandai topik はは sebelum pola ～ように言いました yang menyampaikan instruksi tidak langsung (Pel.47).', 'Bab 46–50 · Mondai 3 No.25', 'materi:book2:21:0'),
  (46, 'published', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>でんわを</span><span class="arrange-chip"><b>②</b>くださいと</span><span class="arrange-chip"><b>③</b>たなかさん</span><span class="arrange-chip"><b>④</b>いただけませんか。</span><span class="arrange-chip"><b>⑤</b>に</span><span class="arrange-chip"><b>⑥</b>つたえて</span></div><small>Petunjuk arti: “Bisakah Anda menyampaikan kepada Tanaka agar menelepon saya?”</small>', '["③→⑤→①→②→⑥→④","⑤→③→①→②→⑥→④","③→①→⑤→②→⑥→④","③→⑤→②→①→⑥→④"]'::jsonb, 0, 'Urutan yang benar: ③たなかさん→⑤に→①でんわを→②くださいと→⑥つたえて→④いただけませんか。 に menandai penerima pesan sebelum pola ～と伝えていただけませんか yang meminta tolong menyampaikan pesan dengan sopan (Pel.47).', 'Bab 46–50 · Mondai 3 No.26', 'materi:book2:21:0'),
  (46, 'published', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>からです。</span><span class="arrange-chip"><b>②</b>べんきょうする</span><span class="arrange-chip"><b>③</b>の</span><span class="arrange-chip"><b>④</b>にほんご</span><span class="arrange-chip"><b>⑤</b>にほんで</span><span class="arrange-chip"><b>⑥</b>を</span><span class="arrange-chip"><b>⑦</b>は</span><span class="arrange-chip"><b>⑧</b>はたらきたい</span></div><small>Petunjuk arti: “Saya belajar bahasa Jepang karena ingin bekerja di Jepang.”</small>', '["④→⑥→②→③→⑦→⑤→⑧→①","⑥→④→②→③→⑦→⑤→⑧→①","④→②→⑥→③→⑦→⑤→⑧→①","④→⑥→③→②→⑦→⑤→⑧→①"]'::jsonb, 0, 'Urutan yang benar: ④にほんご→⑥を→②べんきょうする→③の→⑦は→⑤にほんで→⑧はたらきたい→①からです。 の menominalkan べんきょうする sebelum は pada pola ～のは～からです yang menjelaskan alasan dengan bentuk nominal (Pel.48).', 'Bab 46–50 · Mondai 3 No.27', 'materi:book2:22:0'),
  (46, 'published', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>ために</span><span class="arrange-chip"><b>③</b>たいふう</span><span class="arrange-chip"><b>④</b>とまりました。</span><span class="arrange-chip"><b>⑤</b>でんしゃ</span><span class="arrange-chip"><b>⑥</b>の</span></div><small>Petunjuk arti: “Karena topan, kereta berhenti.”</small>', '["③→⑥→②→⑤→①→④","⑥→③→②→⑤→①→④","③→②→⑥→⑤→①→④","③→⑥→⑤→②→①→④"]'::jsonb, 0, 'Urutan yang benar: ③たいふう→⑥の→②ために→⑤でんしゃ→①が→④とまりました。 の menghubungkan Kata Benda dengan ために pada pola Nのために untuk menyatakan sebab secara formal, dipakai sebelum akibatnya でんしゃがとまりました (Pel.48).', 'Bab 46–50 · Mondai 3 No.28', 'materi:book2:22:0'),
  (46, 'published', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>すわります。</span><span class="arrange-chip"><b>②</b>ように</span><span class="arrange-chip"><b>③</b>まえ</span><span class="arrange-chip"><b>④</b>に</span><span class="arrange-chip"><b>⑤</b>みえる</span><span class="arrange-chip"><b>⑥</b>よく</span></div><small>Petunjuk arti: “Saya duduk di depan agar terlihat jelas.”</small>', '["⑥→⑤→②→③→④→①","⑤→⑥→②→③→④→①","⑥→②→⑤→③→④→①","⑥→⑤→③→②→④→①"]'::jsonb, 0, 'Urutan yang benar: ⑥よく→⑤みえる→②ように→③まえ→④に→①すわります。 に menandai tempat まえ sebelum すわります, didahului anak kalimat tujuan よくみえるように (Pel.48).', 'Bab 46–50 · Mondai 3 No.29', 'materi:book2:22:0'),
  (46, 'published', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>もう</span><span class="arrange-chip"><b>②</b>なりました。</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>おかえりに</span><span class="arrange-chip"><b>⑤</b>ぶちょう</span></div><small>Petunjuk arti: “Kepala bagian sudah pulang.”</small>', '["⑤→③→①→④→②","③→⑤→①→④→②","⑤→①→③→④→②","⑤→③→④→①→②"]'::jsonb, 0, 'Urutan yang benar: ⑤ぶちょう→③は→①もう→④おかえりに→②なりました。 は menandai topik ぶちょう sebelum pola お帰りになりました yang menyatakan tindakan orang yang dihormati (Pel.49).', 'Bab 46–50 · Mondai 3 No.30', 'materi:book2:23:0'),
  (46, 'published', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>こちら</span><span class="arrange-chip"><b>②</b>ごらん</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>ください。</span></div><small>Petunjuk arti: “Silakan lihat ini.”</small>', '["①→③→②→④","③→①→②→④","①→②→③→④","①→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ①こちら→③を→②ごらん→④ください。 Pola お／ご～ください dipakai untuk meminta dengan sangat sopan, di sini bersama ご覧ください (Pel.49).', 'Bab 46–50 · Mondai 4 No.31', 'materi:book2:23:0'),
  (46, 'published', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>します。</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>おもち</span><span class="arrange-chip"><b>④</b>にもつ</span></div><small>Petunjuk arti: “Saya akan membawakan barang Anda.”</small>', '["④→②→③→①","②→④→③→①","④→③→②→①","④→②→①→③"]'::jsonb, 0, 'Urutan yang benar: ④にもつ→②を→③おもち→①します。 Pola お／ご～します merendahkan tindakan pembicara sendiri untuk menghormati lawan bicara, di sini bersama お持ちします (Pel.49).', 'Bab 46–50 · Mondai 4 No.32', 'materi:book2:23:0'),
  (46, 'published', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>あったら</span><span class="arrange-chip"><b>②</b>ふくしゅうして</span><span class="arrange-chip"><b>③</b>ください。</span><span class="arrange-chip"><b>④</b>じかん</span><span class="arrange-chip"><b>⑤</b>が</span></div><small>Petunjuk arti: “Jika ada waktu, silakan mengulang pelajaran.”</small>', '["④→⑤→①→②→③","⑤→④→①→②→③","④→①→⑤→②→③","④→⑤→②→①→③"]'::jsonb, 0, 'Urutan yang benar: ④じかん→⑤が→①あったら→②ふくしゅうして→③ください。 Pola ～たら menyatakan pengandaian dan sekaligus saran sesuai situasi yang mungkin terjadi (Pel.50).', 'Bab 46–50 · Mondai 4 No.33', 'materi:book2:24:0'),
  (46, 'published', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>おもいます。</span><span class="arrange-chip"><b>②</b>これからも</span><span class="arrange-chip"><b>③</b>べんきょうを</span><span class="arrange-chip"><b>④</b>と</span><span class="arrange-chip"><b>⑤</b>つづけよう</span></div><small>Petunjuk arti: “Saya berpikir akan terus belajar mulai sekarang juga.”</small>', '["②→③→⑤→④→①","③→②→⑤→④→①","②→⑤→③→④→①","②→③→④→⑤→①"]'::jsonb, 0, 'Urutan yang benar: ②これからも→③べんきょうを→⑤つづけよう→④と→①おもいます。 Pola 普通形＋と思います menyatakan pendapat atau rencana pribadi pembicara sendiri (Pel.50).', 'Bab 46–50 · Mondai 4 No.34', 'materi:book2:24:0'),
  (46, 'published', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>まいにち</span><span class="arrange-chip"><b>②</b>しています。</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>ように</span><span class="arrange-chip"><b>⑤</b>にほんご</span><span class="arrange-chip"><b>⑥</b>よむ</span></div><small>Petunjuk arti: “Saya membiasakan membaca bahasa Jepang setiap hari.”</small>', '["①→⑤→③→⑥→④→②","⑤→①→③→⑥→④→②","①→③→⑤→⑥→④→②","①→⑤→⑥→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ①まいにち→⑤にほんご→③を→⑥よむ→④ように→②しています。 Pola ～ようにしています menyatakan kebiasaan yang diusahakan secara berkelanjutan, berbeda dari niat sesaat (Pel.50).', 'Bab 46–50 · Mondai 4 No.35', 'materi:book2:24:0'),
  (46, 'published', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'いま　ごはんを　たべたところです。でも、はは　に　でんわしている　ところです、と　うそを　いいました。<br><small>ほんとうは、いま　なにを　していますか。</small>', '["ごはんを たべたばかり","でんわをしているところ","でかけているところ","ねているところ"]'::jsonb, 0, 'Vたところです menyatakan tindakan yang BARU SAJA SELESAI (baru makan), berbeda dari Vているところです yang menyatakan tindakan SEDANG BERLANGSUNG (sedang menelepon) — yang sungguhan terjadi di sini adalah yang pertama (Pel.46).', 'Bab 46–50 · Soal Cerita No.36', 'materi:book2:20:0'),
  (46, 'published', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'せんせいに、もっと　れんしゅうしなさいと　いわれました。だから、はは　に、はやく　ねるように　いいました。<br><small>「はやく　ねるように　いいました」は、だれが　だれに　いいましたか。</small>', '["わたしが ははに","ははが わたしに","せんせいが わたしに","わたしが せんせいに"]'::jsonb, 1, '～ように言いました menyampaikan instruksi TIDAK LANGSUNG dari subjek kalimat (はは) kepada objek (に) — jadi ibu yang menyuruh saya, bukan sebaliknya; berbeda dari ～と言われました yang menyampaikan perkataan yang diterima DARI orang lain (Pel.47).', 'Bab 46–50 · Soal Cerita No.37', 'materi:book2:21:0'),
  (46, 'published', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'にほんごを　べんきょうするのは、にほんで　はたらきたいからです。にほんで　はたらく　ために、まいにち　れんしゅうしています。<br><small>「べんきょうするのは～からです」で　せつめいしている ことは、なんですか。</small>', '["べんきょうする りゆう","れんしゅうする ばしょ","はたらく かいしゃ","にほんごの レベル"]'::jsonb, 0, '～のは～からです menjelaskan ALASAN dari suatu keadaan dengan bentuk nominal, sedangkan ために pada kalimat kedua menyatakan TUJUAN dari tindakan れんしゅうしています — dua pola berbeda fungsi meski sama-sama berkaitan dengan はたらきたい (Pel.48).', 'Bab 46–50 · Soal Cerita No.38', 'materi:book2:22:0'),
  (46, 'published', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ぶちょうは　もう　おかえりに　なりました。わたしは　ぶちょうの　にもつを　おもちしました。<br><small>「おもちしました」を したのは、だれですか。</small>', '["ぶちょう","わたし","かいしゃ","おきゃくさま"]'::jsonb, 1, 'お持ちします adalah pola お／ご～します yang MERENDAHKAN tindakan PEMBICARA SENDIRI (saya yang membawakan), berbeda dari お帰りになりました yang MENGHORMATI tindakan orang lain (kepala bagian yang pulang) (Pel.49).', 'Bab 46–50 · Soal Cerita No.39', 'materi:book2:23:0'),
  (46, 'published', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは、まいにち　にほんごを　よむように　しています。じかんが　あったら、ふくしゅうも　します。これからも　べんきょうを　つづけようと　おもいます。<br><small>まいにち　かならず　して　いる ことは、なんですか。</small>', '["にほんごを よむこと","ふくしゅうすること","じかんを つくること","あたらしいことを はじめること"]'::jsonb, 0, '～ようにしています menyatakan KEBIASAAN yang diusahakan secara BERKELANJUTAN (setiap hari membaca), berbeda dari ～たら yang hanya SYARAT bersyarat (jika ada waktu, baru mengulang) — hanya yang pertama pasti dilakukan tiap hari (Pel.50).', 'Bab 46–50 · Soal Cerita No.40', 'materi:book2:24:0');
